import java.util.*;import java.util.jar.*;import org.objectweb.asm.*;import org.objectweb.asm.tree.*;
/** Pure facts from the pinned archive; never initializes game classes. */
public final class SourceKiringkuCallSites {
 public static void main(String[]a)throws Exception{try(var jar=new JarFile(a[0])){for(var entry:Collections.list(jar.entries()))if(entry.getName().endsWith(".class")){var c=new ClassNode();new ClassReader(jar.getInputStream(entry)).accept(c,ClassReader.SKIP_DEBUG|ClassReader.SKIP_FRAMES);for(var m:c.methods){boolean match=false;for(var n:m.instructions)if(n instanceof MethodInsnNode call&&call.owner.contains("Kiringku")&&call.name.equals("effectGfx"))match=true;if(match){System.out.println("METHOD "+c.name+'.'+m.name+m.desc);int index=0;for(var n:m.instructions){if(n instanceof MethodInsnNode call&&(call.owner.contains("Kiringku")||call.owner.endsWith("Protocol")||call.name.contains("Damage")||call.name.contains("damage")))System.out.println(index+" CALL "+call.owner+'.'+call.name+call.desc);if(n instanceof MethodInsnNode call&&call.name.equals("effectGfx")){int k=0;for(var p=n.getPrevious();p!=null&&k++<10;p=p.getPrevious())System.out.println(" BEFORE "+p.getOpcode()+" "+(p instanceof VarInsnNode v?v.var:p instanceof MethodInsnNode x?x.owner+'.'+x.name+x.desc:""));}index++;}}}}}}
}
